using QuantForge.Governance; using Xunit; namespace QuantForge.ArchitectureTests; public class LiveAuditContinuityV22_65ArchitectureChecks { [Fact] public void ChainHeadMustMatchVerifiedHead(){var t=DateTimeOffset.UtcNow;Assert.True(LiveAuditContinuityGateV22_65.IsCurrent(new("h","h",true,t),t,TimeSpan.FromMinutes(5)));Assert.False(LiveAuditContinuityGateV22_65.IsCurrent(new("h","x",true,t),t,TimeSpan.FromMinutes(5)));} [Fact] public void StaleAuditFailsClosed(){var t=DateTimeOffset.UtcNow;Assert.False(LiveAuditContinuityGateV22_65.IsCurrent(new("h","h",true,t.AddMinutes(-6)),t,TimeSpan.FromMinutes(5)));}}
